import std.io

pub type AppError = Failed(String)

record Cell { n: Int64 }
byval record Val { n: Int64 }

impl Cell {
    fn bump(mut self) {
        self.n = self.n + 10
    }
}

pub fn main() effect io -> Result<(), AppError> {
    let cs = [Cell { n: 1 }, Cell { n: 2 }]
    let acc = 0
    for c in cs { acc = acc + c.n }
    if acc == 3 { io.println("gc-sum-ok") } else { io.println("gc-sum-bad") }

    for c in cs { c.bump() }
    let after = 0
    for c in cs { after = after + c.n }
    if after == 23 { io.println("gc-share-ok") } else { io.println("gc-share-bad") }

    let vs = [Val { n: 1 }, Val { n: 2 }]
    let kept = 0
    for v in vs { kept = kept + v.n }
    if kept == 3 { io.println("val-read-ok") } else { io.println("val-read-bad") }

    return Ok(())
}
